python3 << 'PY'
import workcell, time
def avg_locate(name, n=5):
    xs=[]; ys=[]
    for i in range(n):
        r=workcell.call("robot","locate",name)
        print(r.text)
        xs.append(r.data['x']); ys.append(r.data['y'])
    return sum(xs)/len(xs), sum(ys)/len(ys)
for b in ["B1","B2","B3","B4"]:
    x,y=avg_locate(b, n=3)
    print(f"AVG {b} {x:.4f} {y:.4f}")
PY

